#include <PubSubClient.h>
#include <WiFi.h>
WiFiClient w; PubSubClient mqtt(w);
void cb(char *topic, byte *payload, unsigned int len) {
    digitalWrite({{control_pin}}, payload[0] == '1' ? HIGH : LOW);
}
void setup() {
    pinMode({{control_pin}}, OUTPUT);
    mqtt.setServer("{{broker}}", 1883);
    mqtt.setCallback(cb);
    mqtt.connect("dev");
    mqtt.subscribe("{{topic}}");
}
void loop() { mqtt.loop(); }
